-- Ruler of the Skies (B4) per-card acquisition probabilities.
-- Sources checked 2026-07-30:
-- https://bulbapedia.bulbagarden.net/wiki/Ruler_of_the_Skies_(TCG_Pocket)#Offering_rates
-- https://pocket.limitlesstcg.com/cards/B4
--
-- Definition used by card_pack_odds.pull_probability:
-- P(the card appears at least once in one opened pack).
--
-- Published Ruler of the Skies pack-type rates:
--   regular pack:            94.711%
--   regular pack + 1 card:    5.238%
--   rare pack:                0.050%
--
-- In regular packs with a bonus card, Bulbapedia states that the first five
-- cards use the same rates as regular packs without a bonus card. Shiny cards
-- are only available in the sixth-card bonus slot.
--
-- The source publishes per-card rates rounded to three decimal percentage
-- points. These calculations intentionally use those published values.
--
-- Bulbapedia separates one-star and two-star shiny rates from regular
-- one-star and two-star rates. Limitless renders these with the same visible
-- star glyphs in the list view, so this seed applies shiny rates by collector
-- number: B4-204 through B4-223 are shiny_1 and B4-224 through B4-231 are
-- shiny_2.

begin;

insert into public.card_pack_odds (
  pack_id,
  card_id,
  pull_probability,
  source_note,
  verified_at
)
values
  ('b4-ruler-of-the-skies', 'B4-001', 0.0447420797::numeric, 'Derived from Ruler of the Skies Offering Rates and Limitless card list; includes regular, regular-plus-bonus, and rare pack paths; cards B4-204 through B4-223 use shiny_1 rates and cards B4-224 through B4-231 use shiny_2 rates; probability means at least once per opened pack.', date '2026-07-30'),
