on conflict (pack_id, card_id) do update set
  pull_probability = excluded.pull_probability,
  source_note = excluded.source_note,
  verified_at = excluded.verified_at,
  updated_at = now();

-- Stop and roll back if the catalog, pack, or generated odds are incomplete.
do $$
declare
  ruler_of_the_skies_cards integer;
  ruler_of_the_skies_packs integer;
  ruler_of_the_skies_odds integer;
begin
  select count(*)
  into ruler_of_the_skies_cards
  from public.cards
  where set_id = 'B4';

  select count(*)
  into ruler_of_the_skies_packs
  from public.packs
  where set_id = 'B4';

  select count(*)
  into ruler_of_the_skies_odds
  from public.card_pack_odds
  where pack_id = 'b4-ruler-of-the-skies';

  if ruler_of_the_skies_cards <> 233 then
    raise exception
      'Expected 233 Ruler of the Skies cards, found %',
      ruler_of_the_skies_cards;
  end if;

  if ruler_of_the_skies_packs <> 1 then
    raise exception
      'Expected 1 Ruler of the Skies pack, found %',
      ruler_of_the_skies_packs;
  end if;

  if ruler_of_the_skies_odds <> 233 then
    raise exception
      'Expected 233 Ruler of the Skies odds rows, found %',
      ruler_of_the_skies_odds;
  end if;
end
$$;

commit;

-- Expected: 233 total records for the Ruler of the Skies pack.
select
  cards.rarity,
  count(*) as cards,
  min(card_pack_odds.pull_probability) as min_pull_probability,
  max(card_pack_odds.pull_probability) as max_pull_probability
from public.card_pack_odds
join public.cards
  on cards.id = card_pack_odds.card_id
where card_pack_odds.pack_id = 'b4-ruler-of-the-skies'
group by cards.rarity
order by min(cards.collector_number);
